/*
 * Describes a USB vendor and locates its devices in usb_devices[].
 * device_offset + device_count define the contiguous slice for this vendor.
 */
typedef struct {
	uint16_t    vendor;
	uint32_t    device_offset;  /* Index of first device in usb_devices[] */
	uint32_t    device_count;   /* Number of consecutive devices          */
	const char* name;
} usb_vendor_t;

